-- Keep the home and chat response small. Existing clients still receive the
-- original category and any saved courses during the database-first release.
create or replace function public.elearning_workspace() returns jsonb
language sql stable security definer set search_path='' as $$
  select case when (select private.affairs_google_identity()) then jsonb_build_object(
    'userId',(select auth.uid()),
    'categories',(select coalesce(jsonb_agg(to_jsonb(c) order by c.position),'[]'::jsonb) from public.elearning_categories c),
    'courses',(select coalesce(jsonb_agg(to_jsonb(c) order by c.category_id,c.position),'[]'::jsonb)
      from public.elearning_courses c where c.category_id=41 or exists(
        select 1 from public.elearning_enrollments e where e.user_id=(select auth.uid()) and e.course_id=c.id)),
    'notices',(select coalesce(jsonb_agg(to_jsonb(n) order by n.position),'[]'::jsonb) from public.elearning_notices n),
    'enrollments',(select coalesce(jsonb_agg(jsonb_build_object('courseId',e.course_id,'joinedAt',e.joined_at) order by e.joined_at,e.course_id),'[]'::jsonb)
      from public.elearning_enrollments e where e.user_id=(select auth.uid()))
  ) end;
$$;

create function public.elearning_catalog(p_category integer, p_term text, p_page integer, p_course integer)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare
  owner_id uuid:=(select auth.uid());
  page_size constant integer:=20;
  result jsonb;
begin
  if owner_id is null or not(select private.affairs_google_identity()) then
    raise exception 'Verified School Affairs sign-in required' using errcode='42501';
  end if;
  if p_page is null or p_page not between 1 and 1000 or p_term is null or length(p_term)>100
    or p_category<=0 or p_course<=0 or (p_category is not null and p_course is not null)
    or (p_course is not null and (p_term<>'' or p_page<>1)) then
    raise exception 'Invalid catalog filter' using errcode='22023';
  end if;
  with matching as materialized (
    select c.id,c.category_id,c.title,c.self_enroll,c.position from public.elearning_courses c
    where (p_category is null or c.category_id=p_category)
      and (p_course is null or c.id=p_course)
      and (p_term='' or strpos(lower(normalize(c.title,NFKC)),lower(normalize(p_term,NFKC)))>0)
  ), page_rows as (
    select * from matching order by category_id,position,id limit page_size offset (p_page-1)*page_size
  )
  select jsonb_build_object(
    'userId',owner_id,
    'total',(select count(*) from matching),
    'courses',(select coalesce(jsonb_agg(to_jsonb(r) order by r.category_id,r.position,r.id),'[]'::jsonb) from page_rows r)
  ) into result;
  return result;
end;
$$;
revoke all on function public.elearning_catalog(integer,text,integer,integer) from public,anon;
grant execute on function public.elearning_catalog(integer,text,integer,integer) to authenticated;
